string private _symbol;
uint8 private _decimals;

constructor(
string memory name,
string memory symbol,
uint8 decimals,
address account,
uint256 amount
) public {
_name = name;
_symbol = symbol;
_decimals = decimals;
_mint(account, amount * 10 ** uint256(decimals));
}

